import type { LottieAnimationId } from "../data/lottie";

/**
 * Purely decorative scenery — unlike DestinationPin, never routed to.
 * Generated by `npm run build:lottie`, which fits each animation over the
 * base.svg art it replaces (see tools/lottie/register.ts); don't hand-edit.
 */
export type LottieMarkerConfig = {
  id: string;
  file: LottieAnimationId;
  /** The Lottie comp's own width/height, in its pixels. */
  size: [number, number];
  /**
   * CSS matrix() from comp pixels to map units (artwork pixels), applied
   * with a 0 0 origin — carries the art's scale, rotation and position, so
   * it scales with zoom like the road art rather than staying a fixed
   * screen size like a marker icon.
   */
  matrix: [number, number, number, number, number, number];
};
